/*
 * A042877  Denominators of continued fraction convergents to sqrt(970).
 * https://oeis.org/A042877
 *
 * Offset:    0    (a(0) is the first term)
 * Keywords:  nonn, frac, easy
 * Formula:   a(n) = denominator of the n-th convergent of the continued
 *            fraction for √970. The convergents (p_k/q_k) are generated by
 *            the recurrence q_k = a_k * q_{k-1} + q_{k-2} with initial values
 *            q_{-2}=1, q_{-1}=0 and a_0=⌊√970⌋=31. The partial quotients a_k
 *            for k≥1 are obtained from the standard algorith...
 * Range:     u8 n <= 5, u16 n <= 8, u32 n <= 16, u64 n <= 29, u128 n <= 61,
 *            big any n
 * Helpers:   none
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

seq_t a(idx_t n)
{
    /* 970 is not a perfect square; its continued fraction is periodic. */
    const idx_t D   = 970;     /* value under the square root       */
    const idx_t a0  = 31;      /* ⌊√970⌋, the first term of the CF    */

    /* Denominators: q_-2 = 1, q_-1 = 0.  For n=0 the denominator is 1. */
    seq_t q_prev2 = (seq_t)1;  /* q_{-2}                                */
    seq_t q_prev1 = (seq_t)0;  /* q_{-1}                                */

    /* State for computing the continued‑fraction terms. */
    idx_t m = 0;               /* numerator component in the algorithm    */
    idx_t d = 1;               /* denominator component in the algorithm  */
    seq_t a_k = (seq_t)a0;     /* current partial quotient a_k             */

    /* Iterate until we reach index n. */
    for (idx_t k = 0; k <= n; ++k)
    {
        /* Denominator of the k-th convergent. */
        seq_t q = a_k * q_prev1 + q_prev2;

        if (k == n)                /* finished – return the result       */
            return q;

        /* Compute next partial quotient a_{k+1}. */
        m = d * (idx_t)a_k - m;    /* m = d * a_k - m                    */
        d = (D - m * m) / d;       /* d = (D - m^2) / d                  */
        idx_t next_a = (a0 + m) / d;
        a_k = (seq_t)next_a;       /* store a_{k+1}                       */

        /* Shift denominator values for next iteration. */
        q_prev2 = q_prev1;
        q_prev1 = q;
    }

    /* Should never reach here for non‑negative n. */
    return (seq_t)0;
}
